import type {
  ManageIndexesApi,
  RestoreJobList,
} from '../../pinecone-generated-ts-fetch/db_control';
import { X_PINECONE_API_VERSION } from '../../pinecone-generated-ts-fetch/db_control';
import { handleApiError } from '../../errors/handling';

export type { RestoreJobList } from '../../pinecone-generated-ts-fetch/db_control';

/**
 * Options for listing restore jobs.
 *
 * @see [Backups](https://docs.pinecone.io/guides/indexes/backups)
 */
export interface ListRestoreJobsOptions {
  /** Maximum number of jobs per page. Omit to use the service default. */
  limit?: number;
  /** Pagination token from a previous response. */
  paginationToken?: string;
}

/**
 * Lists all restore jobs for the current project.
 *
 * @param api - The manage-indexes API client.
 * @param options - Optional pagination parameters (limit, paginationToken).
 * @see [Backups](https://docs.pinecone.io/guides/indexes/backups)
 */
export const listRestoreJobs = async (
  api: ManageIndexesApi,
  options?: ListRestoreJobsOptions,
): Promise<RestoreJobList> => {
  try {
    return await api.listRestoreJobs({
      limit: options?.limit,
      paginationToken: options?.paginationToken,
      xPineconeApiVersion: X_PINECONE_API_VERSION,
    });
  } catch (e) {
    throw await handleApiError(
      e,
      async (_, rawMessageText) =>
        `Error listing restore jobs: ${rawMessageText}`,
    );
  }
};
